export function docMigrationScope(ignored: string[] = []): Scope {
  return {
    readable: [`${DOCS_DIR}/**`, README_GLOB, SPECS_GLOB],
    // Nothing is written outright: a cut is offered, never made, until the user agrees.
    writable: [],
    // The docs are the user's: each cut or rewrite is one confirmed write.
    askable: [`${DOCS_DIR}/**`],
    ignored,
  }
}

input.new_string:
export function docMigrationScope(ignored: string[] = []): Scope {
  return {
    readable: [`${DOCS_DIR}/**`, README_GLOB, SPECS_GLOB, UNFILED_FILE],
    // A doc cut is offered, never made, until the user agrees. A ruling that a
    // doc is current is already the user's word, not a new write to confirm:
    // recording it is this job's own bookkeeping, like a planner's.
    writable: [UNFILED_FILE],
    // The docs are the user's: each cut or rewrite is one confirmed write.
    askable: [`${DOCS_DIR}/**`],
    ignored,
  }
}

